/** Build-time SR-1 guard: every seeded cell text must be printed inside the row's own quote span. */
function inSpan(quote: string, cell: string | null, where: string): void {
  if (cell === null) return;
  for (const frag of cell.split('\n')) if (frag.length && !quote.includes(frag)) throw new Error(`${where}: cell "${frag}" is not inside its verbatim_quote`);
}
const num = (name: string): ValueColumn => ({ name, type: 'number' });
const str = (name: string): ValueColumn => ({ name, type: 'string' });

export type T1Row = { code: string; designation: string; notes: string | null; level: 1 | 2 | 3; parent: string | null; kg1: string; kg2: string | null; kg1_key: string; line: number; endLine?: number; span: string };
export type UnitRow = { code: string; designation_kg: string; unit: string | null; unit_tex: string | null; designation: string | null; determination: string | null; line: number; spanFrom?: number; spanTo?: number; span: string };
export type T4Row = { code: string; nr: string; item: string; unit: string | null; unit_tex: string | null; designation: string | null; determination: string | null; line: number; spanFrom?: number; spanTo?: number; span: string };

