// ---------------------------------------------------------------------------
// Builders
// ---------------------------------------------------------------------------
const kgToken = (code: string) => `kg_${code}`;
const T1_BY_CODE = new Map(T1_ROWS.map((r) => [r.code, r]));
/** Group label of a TABLE1 row for the register row picker (`lookup.group_by = 'group_label'`): its parent KG (level 2 / 3) or the first level. */
function t1GroupLabel(r: T1Row): string {
  if (r.level === 1) return 'KG 100–800 (1. Ebene)';
  const p = T1_BY_CODE.get(r.parent!.slice(3))!;
  return `KG ${p.code} ${p.designation}`;
}

export function table1AsTable(): RegulationTable {
  const rows: RegulationRow[] = T1_ROWS.map((r, i) => {
    const where = `TABLE1 ${r.code} (L${r.line})`;
    inSpan(r.span, r.code, where);
    inSpan(r.span, r.designation, where);
    inSpan(r.span, r.notes, where);
    return { row_key: kgToken(r.code), keys: { kg: kgToken(r.code) }, group_label: t1GroupLabel(r), label_de: `${r.code} ${r.designation}`, order_index: i,
      values: { designation: r.designation, notes: r.notes, level: r.level, parent_kg: r.parent, kg1: r.kg1, kg2: r.kg2, kg1_key: r.kg1_key }, verbatim_quote: r.span };
  });
  return { standard_code: STD, edition: ED, table_code: 'TABLE1', title_de: 'Table 1 — Cost breakdown (Kostengliederung KG 100–890: Code, Bezeichnung, Hinweise; Ebene, übergeordnete KG und Ebene-1/-2-Zugehörigkeit strukturell)', clause_reference: '§5.1, §5.4, Table 1', page_ref: null,
    key_columns: ['kg'], value_columns: [str('designation'), str('notes'), num('level'), str('parent_kg'), str('kg1'), str('kg2'), str('kg1_key')],
    override_policy: 'anhaltswert', override_quote: `${Q.L457} — ${Q.L215}`, // notes are examples (anhaltswert); the classification system itself is binding
    verification_status: 'md_verified', rows };
}

function unitRows(rows: ReadonlyArray<UnitRow>, table: string): RegulationRow[] {
  return rows.map((r, i) => {
    const where = `${table} ${r.code} (L${r.line})`;
    inSpan(r.span, r.code, where);
    inSpan(r.span, r.designation_kg, where);
    inSpan(r.span, r.unit_tex, where);
    inSpan(r.span, r.designation, where);
    inSpan(r.span, r.determination, where);
    return { row_key: kgToken(r.code), keys: { kg: kgToken(r.code) }, group_label: null, label_de: `${r.code} ${r.designation_kg}`, order_index: i,
      values: { unit: r.unit, designation: r.designation, determination: r.determination }, verbatim_quote: r.span };
  });
}
export function table2AsTable(): RegulationTable {
  return { standard_code: STD, edition: ED, table_code: 'TABLE2', title_de: 'Table 2 — Quantities and reference units of the first level of the cost breakdown (KG 100–800: Einheit, Bezeichnung, Ermittlung)', clause_reference: '§6.2, Table 2', page_ref: null,
    key_columns: ['kg'], value_columns: [str('unit'), str('designation'), str('determination')],
    override_policy: 'anhaltswert', override_quote: Q.L1022, // "It is recommended that the quantities and reference units in Table 2 be used …"
    verification_status: 'md_verified', rows: unitRows(T2_ROWS, 'TABLE2') };
}
export function table3AsTable(): RegulationTable {
  return { standard_code: STD, edition: ED, table_code: 'TABLE3', title_de: 'Table 3 — Quantities and reference units for cost group 300 (Einheit, Bezeichnung, Ermittlung je KG 3xx)', clause_reference: '§6.3, Table 3', page_ref: null,
    key_columns: ['kg'], value_columns: [str('unit'), str('designation'), str('determination')],
    override_policy: 'anhaltswert', override_quote: Q.L1044, // "It is recommended that the quantities and reference units in Table 3 be used …"
    verification_status: 'imported_unverified', rows: unitRows(T3_ROWS, 'TABLE3') }; // din276-U-1: row 340 prints an empty unit cell (L1093)
}
export function table4AsTable(): RegulationTable {
  const rows: RegulationRow[] = T4_ROWS.map((r, i) => {
    const where = `TABLE4 ${r.code}/${r.nr} (L${r.line})`;
    inSpan(r.span, r.nr === '0' ? r.code : null, where); // an item row prints no code — its kg is the multirow head it sits under (structural)
    inSpan(r.span, r.nr === '0' ? null : r.nr, where);
    inSpan(r.span, r.item, where);
    inSpan(r.span, r.unit_tex, where);
    inSpan(r.span, r.designation, where);
    inSpan(r.span, r.determination, where);
    return { row_key: `${kgToken(r.code)}|${r.nr}`, keys: { kg: kgToken(r.code), nr: r.nr }, group_label: r.nr === '0' ? null : `KG ${r.code}`, label_de: r.nr === '0' ? `${r.code} ${r.item}` : `${r.code}.${r.nr} ${r.item}`, order_index: i,
      values: { item: r.item, unit: r.unit, designation: r.designation, determination: r.determination }, verbatim_quote: r.span };
  });
  return { standard_code: STD, edition: ED, table_code: 'TABLE4', title_de: 'Table 4 — Quantities and reference units for cost group 400 (erweiterte Gliederung: KG 4xx × Position → Einheit, Bezeichnung, Ermittlung)', clause_reference: '§6.4, Table 4', page_ref: null,
    key_columns: ['kg', 'nr'], value_columns: [str('item'), str('unit'), str('designation'), str('determination')],
    override_policy: 'kann', override_quote: Q.L1166, // "… the extended breakdown in Table 4 with the quantities and reference units can be used …" (din276-O-1 proposes anhaltswert from L1018)
    verification_status: 'imported_unverified', rows }; // din276-U-2: printed-blank / "m." cells (L1287, L1375, L1450)
}

/** The four DIN-276 tables (Plan 3 Task 13). */
export function din276SeedTables(): RegulationTable[] {
  return [table1AsTable(), table2AsTable(), table3AsTable(), table4AsTable()];
}
